    TwistExpander_Polaris_Arx::KDF_B_A_A(PARAMS_KDF);

    //
    // src: [$evocation]
    // dst: [$runic]
    //
    TwistExpander_Polaris_Arx::KDF_B_B_A(PARAMS_KDF);

    //
    // ent: [$evocation]
